from pysat.solvers import Glucose3
import itertools

n = 21
edge_to_var = {}
var_to_edge = {}
var_idx = 1
for i in range(n):
    for j in range(i+1, n):
        edge_to_var[(i,j)] = var_idx
        var_to_edge[var_idx] = (i,j)
        var_idx += 1

num_vars = var_idx - 1

clauses = []
for vertices in itertools.combinations(range(n), 4):
    clause = [edge_to_var[(a,b)] for (a,b) in itertools.combinations(vertices, 2)]
    clauses.append(clause)

for vertices in itertools.combinations(range(n), 5):
    clause = [-edge_to_var[(a,b)] for (a,b) in itertools.combinations(vertices, 2)]
    clauses.append(clause)

solver = Glucose3()
for clause in clauses:
    solver.add_clause(clause)

result = solver.solve()
model = solver.get_model()

solution = []
for idx in range(1, num_vars+1):
    if idx in model:
        solution.append(1)
    elif -idx in model:
        solution.append(0)
    else:
        solution.append(0)

print("Full solution:")
print(solution)

# Verify thoroughly
red_edges = set()
blue_edges = set()
for idx, val in enumerate(solution):
    i, j = var_to_edge[idx+1]
    if val == 0:
        red_edges.add((i,j))
    else:
        blue_edges.add((i,j))

# Check all 4-sets for red K4
red_k4_count = 0
for vertices in itertools.combinations(range(n), 4):
    all_red = True
    for (a,b) in itertools.combinations(vertices, 2):
        if (a,b) not in red_edges:
            all_red = False
            break
    if all_red:
        red_k4_count += 1

# Check all 5-sets for blue K5
blue_k5_count = 0
for vertices in itertools.combinations(range(n), 5):
    all_blue = True
    for (a,b) in itertools.combinations(vertices, 2):
        if (a,b) not in blue_edges:
            all_blue = False
            break
    if all_blue:
        blue_k5_count += 1

print(f"Red K4 count: {red_k4_count}")
print(f"Blue K5 count: {blue_k5_count}")
print(f"Solution valid: {red_k4_count == 0 and blue_k5_count == 0}")

# Count edges
print(f"Red edges: {len(red_edges)}")
print(f"Blue edges: {len(blue_edges)}")
print(f"Total: {len(red_edges) + len(blue_edges)}")
